do $batch$
declare v_course text := 'meteorology-forecasting-foundations'; v_chapter uuid; v_unit uuid;
begin
 if not exists(select 1 from public.academy_courses where id=v_course) then raise exception 'Target course missing'; end if;
 if exists(select 1 from public.academy_lessons where slug like 'applied-aviation-%' or slug like 'applied-marine-%' or slug like 'applied-agriculture-%' or slug like 'applied-energy-%' or slug like 'applied-road-%' or slug like 'applied-airquality-%' or slug like 'applied-hydro-%' or slug like 'applied-urban-%' or slug like 'applied-health-%' or slug like 'applied-climate-%') then raise exception 'Lesson slug conflict: batch already exists'; end if;
 insert into public.academy_chapters(course_id,title,description,sort_order,published) values(v_course,'الأرصاد التطبيقية والخدمات القطاعية المتخصصة','دفعة من 100 درس متقدم تربط علم الأرصاد بالتطبيقات التشغيلية للقطاعات الحيوية والخدمات العامة.',66,false) returning id into v_chapter;
 insert into public.academy_units(chapter_id,title,description,sort_order,published) values(v_chapter,'الأرصاد التشغيلية للطيران والمطارات','تطبيق المعلومات الجوية في تخطيط الرحلات وتشغيل المطارات وتقييم مخاطر الطيران.',1,false) returning id into v_unit;
 insert into public.academy_lessons(course_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title,chapter_id,unit_id)
 select v_course,x.slug,x.title,x.summary,x.content,false,x.sort_order,x.level,x.estimated_minutes,x.learning_objectives,'الأرصاد التطبيقية والخدمات القطاعية المتخصصة','الأرصاد التشغيلية للطيران والمطارات',v_chapter,v_unit
 from jsonb_to_recordset($payload$[{"unit_no":1,"slug":"applied-aviation-01","title":"قراءة METAR وSPECI في السياق التشغيلي","summary":"درس تطبيقي في قراءة METAR وSPECI في السياق التشغيلي ضمن الأرصاد التشغيلية للطيران والمطارات، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع قراءة METAR وSPECI في السياق التشغيلي","تحليل بيانات الأرصاد التشغيلية للطيران والمطارات واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في قراءة METAR وSPECI في السياق التشغيلي"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس تفكيك مجموعات الرياح والرؤية والطقس والسحب والضغط وربطها بزمن الرصد وموقع المطار. ضمن سياق تطبيق المعلومات الجوية في تخطيط الرحلات وتشغيل المطارات وتقييم مخاطر الطيران.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["تقارير METAR وSPECI وسجلات المحطات","نشرات TAF والتعديلات والتنبيهات الجوية","رصد الرياح والرؤية وقاعدة السحب والظواهر الخطرة","خرائط الارتفاعات والرادار والأقمار الصناعية"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد مرحلة التشغيل والموقع والفترة","قارن الرصد الحالي بالتوقع وحدود التشغيل المعتمدة","قيّم المجال الرأسي والجغرافي ولا تعمم الظواهر المحلية","وثق الثقة ومواعيد التحديث"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: قراءة METAR وSPECI في السياق التشغيلي","text":"تقرير افتراضي يصف رياحاً متغيرة ورؤية متدهورة مؤقتاً؛ ميّز الرصد الفعلي عما يحتاج متابعة. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل تقريرين متتابعين وحدد عناصر التغير التي ينبغي إبرازها. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["قراءة مجموعة TAF خارج فترة صلاحيتها","اعتبار غياب الرصد دليلاً على غياب الظاهرة","الخلط بين وصف الطقس وحدود اعتماد الطائرة"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن تفكيك مجموعات الرياح والرؤية والطقس والسحب والضغط وربطها بزمن الرصد وموقع المطار. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع قراءة METAR وSPECI في السياق التشغيلي","تحليل بيانات الأرصاد التشغيلية للطيران والمطارات واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في قراءة METAR وSPECI في السياق التشغيلي"],"level":"advanced","estimated_minutes":35,"sort_order":9360},{"unit_no":1,"slug":"applied-aviation-02","title":"تفسير مجموعات TAF والتعديلات","summary":"درس تطبيقي في تفسير مجموعات TAF والتعديلات ضمن الأرصاد التشغيلية للطيران والمطارات، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع تفسير مجموعات TAF والتعديلات","تحليل بيانات الأرصاد التشغيلية للطيران والمطارات واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في تفسير مجموعات TAF والتعديلات"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس تمييز المجموعات الأساسية وTEMPO وBECMG وPROB وأثرها الزمني. ضمن سياق تطبيق المعلومات الجوية في تخطيط الرحلات وتشغيل المطارات وتقييم مخاطر الطيران.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["تقارير METAR وSPECI وسجلات المحطات","نشرات TAF والتعديلات والتنبيهات الجوية","رصد الرياح والرؤية وقاعدة السحب والظواهر الخطرة","خرائط الارتفاعات والرادار والأقمار الصناعية"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد مرحلة التشغيل والموقع والفترة","قارن الرصد الحالي بالتوقع وحدود التشغيل المعتمدة","قيّم المجال الرأسي والجغرافي ولا تعمم الظواهر المحلية","وثق الثقة ومواعيد التحديث"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: تفسير مجموعات TAF والتعديلات","text":"توقع افتراضي يتضمن تحسناً تدريجياً ثم اضطراباً مؤقتاً؛ لا تعامل الاحتمال كحالة مؤكدة. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"أنشئ خطاً زمنياً وحدد الفترات التي تتطلب مراقبة. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["قراءة مجموعة TAF خارج فترة صلاحيتها","اعتبار غياب الرصد دليلاً على غياب الظاهرة","الخلط بين وصف الطقس وحدود اعتماد الطائرة"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن تمييز المجموعات الأساسية وTEMPO وBECMG وPROB وأثرها الزمني. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع تفسير مجموعات TAF والتعديلات","تحليل بيانات الأرصاد التشغيلية للطيران والمطارات واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في تفسير مجموعات TAF والتعديلات"],"level":"advanced","estimated_minutes":40,"sort_order":9370},{"unit_no":1,"slug":"applied-aviation-03","title":"حساب مركبات الرياح بالنسبة للمدرج","summary":"درس تطبيقي في حساب مركبات الرياح بالنسبة للمدرج ضمن الأرصاد التشغيلية للطيران والمطارات، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع حساب مركبات الرياح بالنسبة للمدرج","تحليل بيانات الأرصاد التشغيلية للطيران والمطارات واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في حساب مركبات الرياح بالنسبة للمدرج"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس فصل المركبة المواجهة والجانبية بتحليل الفرق الزاوي بين اتجاه الرياح ومحور المدرج. ضمن سياق تطبيق المعلومات الجوية في تخطيط الرحلات وتشغيل المطارات وتقييم مخاطر الطيران.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["تقارير METAR وSPECI وسجلات المحطات","نشرات TAF والتعديلات والتنبيهات الجوية","رصد الرياح والرؤية وقاعدة السحب والظواهر الخطرة","خرائط الارتفاعات والرادار والأقمار الصناعية"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد مرحلة التشغيل والموقع والفترة","قارن الرصد الحالي بالتوقع وحدود التشغيل المعتمدة","قيّم المجال الرأسي والجغرافي ولا تعمم الظواهر المحلية","وثق الثقة ومواعيد التحديث"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: حساب مركبات الرياح بالنسبة للمدرج","text":"رياح افتراضية 240 درجة بسرعة 18 عقدة ومدرج 270 درجة؛ احسب المركبتين تقريبياً. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن مدرجين وحدد أيهما يقلل المركبة الجانبية في المثال. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["قراءة مجموعة TAF خارج فترة صلاحيتها","اعتبار غياب الرصد دليلاً على غياب الظاهرة","الخلط بين وصف الطقس وحدود اعتماد الطائرة"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن فصل المركبة المواجهة والجانبية بتحليل الفرق الزاوي بين اتجاه الرياح ومحور المدرج. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع حساب مركبات الرياح بالنسبة للمدرج","تحليل بيانات الأرصاد التشغيلية للطيران والمطارات واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في حساب مركبات الرياح بالنسبة للمدرج"],"level":"advanced","estimated_minutes":45,"sort_order":9380},{"unit_no":1,"slug":"applied-aviation-04","title":"تقييم الهبات والرياح الجانبية","summary":"درس تطبيقي في تقييم الهبات والرياح الجانبية ضمن الأرصاد التشغيلية للطيران والمطارات، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع تقييم الهبات والرياح الجانبية","تحليل بيانات الأرصاد التشغيلية للطيران والمطارات واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في تقييم الهبات والرياح الجانبية"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس التمييز بين متوسط الرياح والهبة القصوى والتغير السريع وتوقيت القياس. ضمن سياق تطبيق المعلومات الجوية في تخطيط الرحلات وتشغيل المطارات وتقييم مخاطر الطيران.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["تقارير METAR وSPECI وسجلات المحطات","نشرات TAF والتعديلات والتنبيهات الجوية","رصد الرياح والرؤية وقاعدة السحب والظواهر الخطرة","خرائط الارتفاعات والرادار والأقمار الصناعية"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد مرحلة التشغيل والموقع والفترة","قارن الرصد الحالي بالتوقع وحدود التشغيل المعتمدة","قيّم المجال الرأسي والجغرافي ولا تعمم الظواهر المحلية","وثق الثقة ومواعيد التحديث"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: تقييم الهبات والرياح الجانبية","text":"تقرير افتراضي متوسطه 12 عقدة وهباته 25 عقدة؛ المتوسط وحده لا يصف التذبذب. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اكتب ملخصاً يذكر المتوسط والهبات والاتجاه والتغير الزمني. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["قراءة مجموعة TAF خارج فترة صلاحيتها","اعتبار غياب الرصد دليلاً على غياب الظاهرة","الخلط بين وصف الطقس وحدود اعتماد الطائرة"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن التمييز بين متوسط الرياح والهبة القصوى والتغير السريع وتوقيت القياس. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع تقييم الهبات والرياح الجانبية","تحليل بيانات الأرصاد التشغيلية للطيران وال