 from jsonb_to_recordset($payload$[{"unit_no":2,"slug":"applied-marine-01","title":"ارتفاع الموج المهم والارتفاع الأقصى","summary":"درس تطبيقي في ارتفاع الموج المهم والارتفاع الأقصى ضمن الأرصاد البحرية والتشغيل الساحلي المتقدم، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع ارتفاع الموج المهم والارتفاع الأقصى","تحليل بيانات الأرصاد البحرية والتشغيل الساحلي المتقدم واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في ارتفاع الموج المهم والارتفاع الأقصى"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس فهم التوزيع الإحصائي لارتفاع الموج وتمييز Hs عن الموجات الفردية الأكبر. ضمن سياق تحويل بيانات الرياح والأمواج والرؤية والمد والجزر إلى معلومات للسفن والموانئ والسواحل.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["رصد العوامات والسفن ومحطات الساحل","توقعات الرياح والأمواج والمد والجزر","خرائط الضغط وحرارة سطح البحر والتيارات","صور الأقمار الصناعية ومنتجات الرادار الساحلي"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الحوض والموقع والعمق والفترة","افصل موج الرياح عن التموج القادم من مناطق بعيدة","قارن التوقع بالرصد مع مراعاة تمثيل العوامة","اربط المنتج بحدود تشغيل الميناء المعتمدة"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: ارتفاع الموج المهم والارتفاع الأقصى","text":"حالة افتراضية Hs فيها 2.5 متر مع فترة طويلة؛ الموجات الفردية قد تتجاوز القيمة التمثيلية. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر نشرة موج وحدد الفرق بين القيمة التمثيلية والقصوى. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["الخلط بين ارتفاع الموج المهم والموجة الفردية القصوى","إهمال اتجاه التموج وفترته","استخدام رصد ساحلي لتمثيل عرض البحر"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن فهم التوزيع الإحصائي لارتفاع الموج وتمييز Hs عن الموجات الفردية الأكبر. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع ارتفاع الموج المهم والارتفاع الأقصى","تحليل بيانات الأرصاد البحرية والتشغيل الساحلي المتقدم واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في ارتفاع الموج المهم والارتفاع الأقصى"],"level":"advanced","estimated_minutes":35,"sort_order":9460},{"unit_no":2,"slug":"applied-marine-02","title":"تمييز موج الرياح عن التموج البحري","summary":"درس تطبيقي في تمييز موج الرياح عن التموج البحري ضمن الأرصاد البحرية والتشغيل الساحلي المتقدم، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع تمييز موج الرياح عن التموج البحري","تحليل بيانات الأرصاد البحرية والتشغيل الساحلي المتقدم واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في تمييز موج الرياح عن التموج البحري"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس تحليل منشأ الموج واتجاهه وفترته وإمكان اجتماع أنظمة موجية. ضمن سياق تحويل بيانات الرياح والأمواج والرؤية والمد والجزر إلى معلومات للسفن والموانئ والسواحل.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["رصد العوامات والسفن ومحطات الساحل","توقعات الرياح والأمواج والمد والجزر","خرائط الضغط وحرارة سطح البحر والتيارات","صور الأقمار الصناعية ومنتجات الرادار الساحلي"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الحوض والموقع والعمق والفترة","افصل موج الرياح عن التموج القادم من مناطق بعيدة","قارن التوقع بالرصد مع مراعاة تمثيل العوامة","اربط المنتج بحدود تشغيل الميناء المعتمدة"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: تمييز موج الرياح عن التموج البحري","text":"عوامة تسجل مجموعتين من الفترات والاتجاهات. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن مخطط الطيف وحدد مكونات النظامين. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["الخلط بين ارتفاع الموج المهم والموجة الفردية القصوى","إهمال اتجاه التموج وفترته","استخدام رصد ساحلي لتمثيل عرض البحر"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن تحليل منشأ الموج واتجاهه وفترته وإمكان اجتماع أنظمة موجية. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع تمييز موج الرياح عن التموج البحري","تحليل بيانات الأرصاد البحرية والتشغيل الساحلي المتقدم واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في تمييز موج الرياح عن التموج