 from jsonb_to_recordset($payload$[{"unit_no":3,"slug":"applied-agriculture-01","title":"حساب الوحدات الحرارية المتراكمة للمحصول","summary":"درس تطبيقي في حساب الوحدات الحرارية المتراكمة للمحصول ضمن الأرصاد الزراعية وإدارة العمليات الحقلية، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع حساب الوحدات الحرارية المتراكمة للمحصول","تحليل بيانات الأرصاد الزراعية وإدارة العمليات الحقلية واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في حساب الوحدات الحرارية المتراكمة للمحصول"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس فهم درجات النمو الحرارية ودرجة الأساس وطريقة التراكم وحدود استخدامها. ضمن سياق تطبيق الرصد والتوقعات في توقيت العمليات ومتابعة الإجهاد المائي والحراري ومخاطر المحاصيل.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["محطات الحقل وحرارة ورطوبة التربة","الإشعاع والرياح والرطوبة والهطول","مرحلة نمو المحصول وخصائص التربة","صور الأقمار الصناعية وسجلات الري"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد المحصول والمرحلة الفينولوجية والموقع","راجع جودة بيانات الحقل وتمثيل المحطة","احسب المؤشر مع ذكر الافتراضات والوحدات","حوّل النتيجة إلى نافذة مراقبة بالتنسيق مع المختص الزراعي"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: حساب الوحدات الحرارية المتراكمة للمحصول","text":"سلسلة يومية افتراضية لدرجات الحرارة ومحصول له درجة أساس تعليمية. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"احسب الوحدات الحرارية لفترة قصيرة وقارنها بمرحلة نمو افتراضية. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["نقل معاملات محصول لآخر دون معايرة","اعتبار محطة واحدة ممثلة لكل الحقول","إهمال نوع التربة وعمق الجذور ومرحلة النمو"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن فهم درجات النمو الحرارية ودرجة الأساس وطريقة التراكم وحدود استخدامها. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع حساب الوحدات الحرارية المتراكمة للمحصول","تحليل بيانات الأرصاد الزراعية وإدارة العمليات الحقلية واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في حساب الوحدات الحرارية المتراكمة للمحصول"],"level":"advanced","estimated_minutes":35,"sort_order":9560},{"unit_no":3,"slug":"applied-agriculture-02","title":"تقدير الاحتياج المائي المرجعي للمحصول","summary":"درس تطبيقي في تقدير الاحتياج المائي المرجعي للمحصول ضمن الأرصاد الزراعية وإدارة العمليات الحقلية، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع تقدير الاحتياج المائي المرجعي للمحصول","تحليل بيانات الأرصاد الزراعية وإدارة العمليات الحقلية واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في تقدير الاحتياج المائي المرجعي للمحصول"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس التمييز بين ET0 والتبخر-نتح الفعلي واستخدام معامل Kc. ضمن سياق تطبيق الرصد والتوقعات في توقيت العمليات ومتابعة الإجهاد المائي والحراري ومخاطر المحاصيل.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["محطات الحقل وحرارة ورطوبة التربة","الإشعاع والرياح والرطوبة والهطول","مرحلة نمو المحصول وخصائص التربة","صور الأقمار الصناعية وسجلات الري"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد المحصول والمرحلة الفينولوجية والموقع","راجع جودة بيانات الحقل وتمثيل المحطة","احسب المؤشر مع ذكر الافتراضات والوحدات","حوّل النتيجة إلى نافذة مراقبة بالتنسيق مع المختص الزراعي"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: تقدير الاحتياج المائي المرجعي للمحصول","text":"قيم ET0 يومية ومعامل Kc مرحلي في مثال حسابي. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"احسب ETc لفترة واشرح أثر مرحلة النمو. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["نقل معاملات محصول لآخر دون معايرة","اعتبار محطة واحدة ممثلة لكل الحقول","إهمال نوع التربة وعمق الجذور ومرحلة النمو"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن التمييز بين ET0 والتبخر-نتح الفعلي واستخدام معامل Kc. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع تقدير الاحتياج المائي المرجعي للمحصول","تحليل بيانات الأرصاد الزراعية وإدارة العمليات الحقلية واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في تقدير الاحتياج المائي المرجعي للمحصول"],"level":"advanced","estimated_minutes":40,"sort_order":9570},{"unit_no":3,"slug":"applied-agriculture-03","title":"ميزانية رطوبة التربة في منطقة الجذور","summary":"درس تطبيقي في ميزانية رطوبة التربة في منطقة الجذور ضمن الأرصاد الزراعية وإدارة العمليات الحقلية، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع ميزانية رطوبة التربة في منطقة الجذور","تحليل بيانات الأرصاد الزراعية وإدارة العمليات الحقلية واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في ميزانية رطوبة التربة في منطقة الجذور"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس تتبع المطر والري والتبخر-نتح والتسرب والتغير في مخزون الماء. ضمن سياق تطبيق الرصد والتوقعات في توقيت العمليات ومتابعة الإجهاد المائي والحراري ومخاطر المحاصيل.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["محطات الحقل وحرارة ورطوبة التربة","الإشعاع والرياح والرطوبة والهطول","مرحلة نمو المحصول وخصائص التربة","صور الأقمار الصناعية وسجلات الري"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد المحصول والمرحلة الفينولوجية والموقع","راجع جودة بيانات الحقل وتمثيل المحطة","احسب المؤشر مع ذكر الافتراضات والوحدات","حوّل النتيجة إلى نافذة مراقبة بالتنسيق مع المختص الزراعي"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: ميزانية رطوبة التربة في منطقة الجذور","text":"قطاع تربة يبدأ بمخزون معروف ويتلقى مطراً ورياً وفقداً يومياً. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"أنشئ ميزانية مائية مبسطة وحدد مصادر عدم اليقين. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["نقل معاملات محصول لآخر دون معايرة","اعتبار محطة واحدة ممثلة لكل الحقول","إهمال نوع التربة وعمق الجذور ومرحلة النمو"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن تتبع المطر والري والتبخر-نتح والتسرب والتغير في مخزون الماء. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع ميزانية رطوبة التربة في منطقة الجذور","تحليل بيانات الأرصاد الزراعية وإدارة العمليات الحقلية واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في ميزانية رطوبة التربة في منطقة الجذور"],"level":"advanced","estimated_minutes":45,"sort_order":9580},{"unit_no":3,"slug":"applied-agriculture-04","title":"اختلاف مخاطر الصقيع بين الحقول","summary":"درس تطبيقي في اختلاف مخاطر الصقيع بين الحقول ضمن الأرصاد الزراعية وإدارة العمليات الحقلية، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع اختلاف مخاطر الصقيع بين الحقول","تحليل بيانات الأرصاد الزراعية وإدارة العمليات الحقلية واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في اختلاف مخاطر الصقيع بين الحقول"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس تحليل التضاريس والتصريف الهوائي والغطاء الأرضي والرطوبة. ضمن سياق تطبيق الرصد والتوقعات في توقيت العمليات ومتابعة الإجهاد المائي والحراري ومخاطر المحاصيل.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها و