 from jsonb_to_recordset($payload$[{"unit_no":4,"slug":"applied-energy-01","title":"مكونات الإشعاع الشمسي GHI وDNI وDHI","summary":"درس تطبيقي في مكونات الإشعاع الشمسي GHI وDNI وDHI ضمن الأرصاد التشغيلية للطاقة المتجددة، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع مكونات الإشعاع الشمسي GHI وDNI وDHI","تحليل بيانات الأرصاد التشغيلية للطاقة المتجددة واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في مكونات الإشعاع الشمسي GHI وDNI وDHI"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس تعريف الإشعاع الكلي والمباشر والمنتشر وعلاقاتها وحدود القياس. ضمن سياق تحويل بيانات الغلاف الجوي إلى توقعات إنتاج وإدارة عدم اليقين في محطات الطاقة الشمسية والرياح.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["الإشعاع الشمسي GHI وDNI وDHI","سرعة الرياح على ارتفاعات مختلفة وحرارة الهواء","بيانات إنتاج المحطة ومنحنيات القدرة","صور الأقمار الصناعية وتوقعات السحب"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد مقياس الإنتاج والفترة الزمنية","افصل مورد الطقس عن أداء المعدات وحالة التشغيل","اربط المتغيرات الجوية بمنحنى المحطة المعاير","تحقق من الانحياز وأحداث التغير السريع"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: مكونات الإشعاع الشمسي GHI وDNI وDHI","text":"محطة افتراضية تسجل مكونات إشعاع مختلفة تحت سماء صافية وغائمة. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر تغير المكونات وحدد الحساس المناسب لكل متغير. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["استخدام رياح السطح بديلاً عن ارتفاع المحور دون تحويل","الخلط بين الإشعاع الأفقي والإشعاع على مستوى اللوح","نسب انخفاض الإنتاج للطقس دون فحص الأعطال"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن تعريف الإشعاع الكلي والمباشر والمنتشر وعلاقاتها وحدود القياس. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع مكونات الإشعاع الشمسي GHI وDNI وDHI","تحليل بيانات الأرصاد التشغيلية للطاقة المتجددة واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في مكونات الإشعاع الشمسي GHI وDNI وDHI"],"level":"advanced","estimated_minutes":35,"sort_order":9660},{"unit_no":4,"slug":"applied-energy-02","title":"التنبؤ بتغير إنتاج الخلايا مع مرور السحب","summary":"درس تطبيقي في التنبؤ بتغير إنتاج الخلايا مع مرور السحب ضمن الأرصاد التشغيلية للطاقة المتجددة، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع التنبؤ بتغير إنتاج الخلايا مع مرور السحب","تحليل بيانات الأرصاد التشغيلية للطاقة المتجددة واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في التنبؤ بتغير إنتاج الخلايا مع مرور السحب"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس ربط سرعة حركة السحب وسمكها ونوعها بمعدلات تغير الإشعاع. ضمن سياق تحويل بيانات الغلاف الجوي إلى توقعات إنتاج وإدارة عدم اليقين في محطات الطاقة الشمسية والرياح.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["الإشعاع الشمسي GHI وDNI وDHI","سرعة الرياح على ارتفاعات مختلفة وحرارة الهواء","بيانات إنتاج المحطة ومنحنيات القدرة","صور الأقمار الصناعية وتوقعات السحب"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد مقياس الإنتاج والفترة الزمنية","افصل مورد الطقس عن أداء المعدات وحالة التشغيل","اربط المتغيرات الجوية بمنحنى المحطة المعاير","تحقق من الانحياز وأحداث التغير السريع"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: التنبؤ بتغير إنتاج الخلايا مع مرور السحب","text":"سحب متقطعة تعبر مصفوفة شمسية في فترة قصيرة. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل صوراً زمنية افتراضية وحدد نافذة تغير الإشعاع. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["استخدام رياح السطح بديلاً عن ارتفاع المحور دون تحويل","الخلط بين الإشعاع الأفقي والإشعاع على مستوى اللوح","نسب انخفاض الإنتاج للطقس دون فحص الأعطال"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن ربط سرعة حركة السحب وسمكها ونوعها بمعدلات تغير الإشعاع. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع التنبؤ بتغير إنتاج الخلايا مع مرور السحب","تحليل بيانات الأرصاد التشغيلية للطاقة المتجددة واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في التنبؤ بتغير إنتا