 from jsonb_to_recordset($payload$[{"unit_no":5,"slug":"applied-road-01","title":"ميزانية حرارة سطح الطريق","summary":"درس تطبيقي في ميزانية حرارة سطح الطريق ضمن أرصاد الطرق والبنية التحتية والنقل، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع ميزانية حرارة سطح الطريق","تحليل بيانات أرصاد الطرق والبنية التحتية والنقل واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في ميزانية حرارة سطح الطريق"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس فهم الإشعاع والتبادل الحسي والحرارة المخزنة والرياح. ضمن سياق تقييم أثر الطقس في سطح الطريق والجسور والسكك الحديدية ومرافق النقل.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["محطات الطقس على الطرق وحساسات سطح الرصف","حرارة الهواء والرصف ونقطة الندى والهطول","كاميرات الطرق وتقارير فرق الصيانة","نماذج محلية وخصائص الطريق والتضاريس"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد المقطع ونوع السطح والتعرض والارتفاع","قارن حرارة السطح بحرارة الهواء والرطوبة والهطول","قيّم التغير المكاني واحتمال تجاوز العتبة المحلية","أصدر وصفاً للمخاطر والثقة والتحديث"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: ميزانية حرارة سطح الطريق","text":"مقطع طريق يتعرض نهاراً للشمس ثم يفقد الحرارة ليلاً. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر الفرق بين حرارة الهواء والرصف عبر دورة يومية. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["استخدام حرارة محطة بعيدة لتقدير الرصف","الخلط بين احتمال الجليد وتأكيد وجوده","إهمال الجسور والمنحدرات والظلال"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن فهم الإشعاع والتبادل الحسي والحرارة المخزنة والرياح. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع ميزانية حرارة سطح الطريق","تحليل بيانات أرصاد الطرق والبنية التحتية والنقل واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في ميزانية حرارة سطح الطريق"],"level":"advanced","estimated_minutes":35,"sort_order":9760},{"unit_no":5,"slug":"applied-road-02","title":"تقدير قابلية تكون الصقيع على الرصف","summary":"درس تطبيقي في تقدير قابلية تكون الصقيع على الرصف ضمن أرصاد الطرق والبنية التحتية والنقل، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع تقدير قابلية تكون الصقيع على الرصف","تحليل بيانات أرصاد الطرق والبنية التحتية والنقل واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في تقدير قابلية تكون الصقيع على الرصف"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس دمج حرارة السطح والرطوبة ونقطة الندى والتبريد الإشعاعي. ضمن سياق تقييم أثر الطقس في سطح الطريق والجسور والسكك الحديدية ومرافق النقل.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["محطات الطقس على الطرق وحساسات سطح الرصف","حرارة الهواء والرصف ونقطة الندى والهطول","كاميرات الطرق وتقارير فرق الصيانة","نماذج محلية وخصائص الطريق والتضاريس"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد المقطع ونوع السطح والتعرض والارتفاع","قارن حرارة السطح بحرارة الهواء والرطوبة والهطول","قيّم التغير المكاني واحتمال تجاوز العتبة المحلية","أصدر وصفاً للمخاطر والثقة والتحديث"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: تقدير قابلية تكون الصقيع على الرصف","text":"ليلة صافية هادئة مع رصف يقترب من التجمد. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد مؤشرات الإنذار وما يلزم تأكيده ميدانياً. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["استخدام حرارة محطة بعيدة لتقدير الرصف","الخلط بين احتمال الجليد وتأكيد وجوده","إهمال الجسور والمنحدرات والظلال"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن دمج حرارة السطح والرطوبة ونقطة الندى والتبريد الإشعاعي. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع تقدير قابلية تكون الصقيع على الرصف","تحليل بيانات أرصاد الطرق والبنية التحتية والنقل واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في تقدير قابلية تكون الصقيع على الرصف"],"level":"advanced","estimated_minutes":40,"sort_order":9770},{"unit_no":5,"slug":"applied-road-03","title":"التمييز بين الجليد الأسود والسطح الرطب","summary":"درس تطبيقي في التمييز بين الجليد الأسود والسطح الرطب ضمن أرصاد ال