 from jsonb_to_recordset($payload$[{"unit_no":6,"slug":"applied-airquality-01","title":"ارتفاع طبقة الخلط والتهوية الجوية","summary":"درس تطبيقي في ارتفاع طبقة الخلط والتهوية الجوية ضمن الأرصاد وجودة الهواء وانتقال الملوثات، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع ارتفاع طبقة الخلط والتهوية الجوية","تحليل بيانات الأرصاد وجودة الهواء وانتقال الملوثات واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في ارتفاع طبقة الخلط والتهوية الجوية"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس أثر عمق الطبقة المختلطة وسرعة الرياح في حجم التخفيف. ضمن سياق تحليل دور الاستقرار والخلط والرياح والرطوبة في تراكم الملوثات وانتقالها.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["محطات PM2.5 وPM10 والغازات ومعايرة الحساسات","ملف الحرارة الرأسي وارتفاع طبقة الخلط","الرياح والإشعاع والهطول","بيانات الانبعاثات والتضاريس والنماذج الكيميائية"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["تحقق من جودة التركيزات ومزامنة الوقت","حلل التهوية وارتفاع الخلط والاستقرار والاتجاه","افصل النقل الإقليمي عن المصادر المحلية حسب الأدلة","اعرض التوقع كتقدير مشروط لا كقياس مباشر"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: ارتفاع طبقة الخلط والتهوية الجوية","text":"يوم افتراضي بطبقة خلط منخفضة ورياح ضعيفة يقابله يوم بخلط عميق. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن معامل التهوية التقريبي وحدد حدود المؤشر. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["نسبة ارتفاع PM إلى مصدر واحد دون دليل","تجاهل تغير الانبعاثات اليومية","الخلط بين مؤشر الجودة والتركيز الخام"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن أثر عمق الطبقة المختلطة وسرعة الرياح في حجم التخفيف. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع ارتفاع طبقة الخلط والتهوية الجوية","تحليل بيانات الأرصاد وجودة الهواء وانتقال الملوثات واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في ارتفاع طبقة الخلط والتهوية الجوية"],"level":"advanced","estimated_minutes":35,"sort_order":9860},{"unit_no":6,"slug":"applied-airquality-02","title":"الانقلاب الحراري وتراكم الملوثات","summary":"درس تطبيقي في الانقلاب الحراري وتراكم الملوثات ضمن الأرصاد وجودة الهواء وانتقال الملوثات، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع الانقلاب الحراري وتراكم الملوثات","تحليل بيانات الأرصاد وجودة الهواء وانتقال الملوثات واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في الانقلاب الحراري وتراكم الملوثات"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس تحليل الانقلاب السطحي والعلوي وتأثيره في كبح الخلط الرأسي. ضمن سياق تحليل دور الاستقرار والخلط والرياح والرطوبة في تراكم الملوثات وانتقالها.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["محطات PM2.5 وPM10 والغازات ومعايرة الحساسات","ملف الحرارة الرأسي وارتفاع طبقة الخلط","الرياح والإشعاع والهطول","بيانات الانبعاثات والتضاريس والنماذج الكيميائية"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["تحقق من جودة التركيزات ومزامنة الوقت","حلل التهوية وارتفاع الخلط والاستقرار والاتجاه","افصل النقل الإقليمي عن المصادر المحلية حسب الأدلة","اعرض التوقع كتقدير مشروط لا كقياس مباشر"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: الانقلاب الحراري وتراكم الملوثات","text":"مسبار رأسي افتراضي يظهر طبقة دافئة فوق هواء أبرد. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد ارتفاع قاعدة الانقلاب وناقش أثرها المحتمل. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["نسبة ارتفاع PM إلى مصدر واحد دون دليل","تجاهل تغير الانبعاثات اليومية","الخلط بين مؤشر الجودة والتركيز الخام"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن تحليل الانقلاب السطحي والعلوي وتأثيره في كبح الخلط الرأسي. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع الانقلاب الحراري وتراكم الملوثات","تحليل بيانات الأرصاد وجودة الهواء وانتقال الملوثات واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في الانقلاب الحراري وتراكم الملوثات"],"level":"advanced","estimated_minutes":40,"sort_order":9870},{"unit_no":6,"slug":"applied-airquality-03",