 from jsonb_to_recordset($payload$[{"unit_no":7,"slug":"applied-hydro-01","title":"عتبات المطر الحرجة حسب الحوض","summary":"درس تطبيقي في عتبات المطر الحرجة حسب الحوض ضمن الأرصاد الهيدرولوجية والإنذار بالفيضانات، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع عتبات المطر الحرجة حسب الحوض","تحليل بيانات الأرصاد الهيدرولوجية والإنذار بالفيضانات واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في عتبات المطر الحرجة حسب الحوض"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس تغير العتبة مع مساحة الحوض والانحدار والتربة وحالة التشبع. ضمن سياق دمج المطر والرادار ورطوبة التربة والأحواض مع التوقعات لدعم الإنذار الهيدرولوجي.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["مقاييس المطر والرادار ومنتجات QPE وQPF","رطوبة التربة والتدفق ومستوى الأنهار","خصائص الحوض والانحدار واستخدام الأرض","سجلات الفيضانات والعتبات المحلية"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الحوض وفترة الاستجابة ومقياس القرار","افحص المطر المرصود والمتوقع وتوزيعه المكاني","ادمج حالة الحوض السابقة وخصائص التصريف","قارن المخرجات بعتبات محلية موثقة"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: عتبات المطر الحرجة حسب الحوض","text":"حوضان افتراضيان يتلقيان المطر نفسه لكن زمن الاستجابة مختلف. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن الحوضين وصمم منطقاً لعتبات مختلفة. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["استخدام عتبة واحدة لكل الأحواض","إهمال رطوبة التربة السابقة","الخلط بين توقع المطر وتوقع التصريف"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن تغير العتبة مع مساحة الحوض والانحدار والتربة وحالة التشبع. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع عتبات المطر الحرجة حسب الحوض","تحليل بيانات الأرصاد الهيدرولوجية والإنذار بالفيضانات واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في عتبات المطر الحرجة حسب الحوض"],"level":"advanced","estimated_minutes":35,"sort_order":9960},{"unit_no":7,"slug":"applied-hydro-02","title":"أثر رطوبة التربة السابقة في الجريان","summary":"درس تطبيقي في أثر رطوبة التربة السابقة في الجريان ضمن الأرصاد الهيدرولوجية والإنذار بالفيضانات، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع أثر رطوبة التربة السابقة في الجريان","تحليل بيانات الأرصاد الهيدرولوجية والإنذار بالفيضانات واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في أثر رطوبة التربة السابقة في الجريان"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس دور التشبع الأولي والتسرب وسعة التخزين في تحويل المطر إلى جريان. ضمن سياق دمج المطر والرادار ورطوبة التربة والأحواض مع التوقعات لدعم الإنذار الهيدرولوجي.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["مقاييس المطر والرادار ومنتجات QPE وQPF","رطوبة التربة والتدفق ومستوى الأنهار","خصائص الحوض والانحدار واستخدام الأرض","سجلات الفيضانات والعتبات المحلية"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الحوض وفترة الاستجابة ومقياس القرار","افحص المطر المرصود والمتوقع وتوزيعه المكاني","ادمج حالة الحوض السابقة وخصائص التصريف","قارن المخرجات بعتبات محلية موثقة"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: أثر رطوبة التربة السابقة في الجريان","text":"عاصفتان متساويتان فوق تربة جافة وأخرى رطبة. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر اختلاف الاستجابة وحدد بيانات التربة المطلوبة. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["استخدام عتبة واحدة لكل الأحواض","إهمال رطوبة التربة السابقة","الخلط بين توقع المطر وتوقع التصريف"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن دور التشبع الأولي والتسرب وسعة التخزين في تحويل المطر إلى جريان. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع أثر رطوبة التربة السابقة في الجريان","تحليل بيانات الأرصاد الهيدرولوجية والإنذار بالفيضانات واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في أثر رطوبة التربة السابقة في الجريان"],"level":"advanced","estimated_minutes":40,"sort_order":9970},{"unit_no":7,"slug":"applied-hydro-03","title":"التحقق من تقدير المطر الراداري QPE","summary":"درس تطبيقي في التحقق من تقدير المطر الراداري QPE ضمن الأرصاد الهيدرولوجية والإنذار بالفيضانات، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع التحقق من تقدير المطر الراداري QPE","تحليل بيانات الأرصاد الهيدرولوجية والإنذار بالفيضانات واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في التحقق من تقدير المطر الراداري QPE"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس فهم التقدير الراداري وعلاقة الانعكاسية بالمطر وتصحيح الانحياز. ضمن سياق دمج المطر والرادار ورطوبة التربة والأحواض مع التوقعات لدعم الإنذار الهيدرولوجي.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["مقاييس المطر والرادار ومنتجات QPE وQPF","رطوبة التربة والتدفق ومستوى الأنهار","خصائص الحوض والانحدار واستخدام الأرض","سجلات الفيضانات والعتبات المحلية"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الحوض وفترة الاستجابة ومقياس القرار","افحص المطر المرصود والمتوقع وتوزيعه المكاني","ادمج حالة الحوض السابقة وخصائص التصريف","قارن المخرجات بعتبات محلية موثقة"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: التحقق من تقدير المطر الراداري QPE","text":"رادار يبالغ في المطر قرب الجبال مقارنة بمقاييس أرضية. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم مقارنة مكانية وزمنية بين الرادار والمقاييس. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["استخدام عتبة واحدة لكل الأحواض","إهمال رطوبة التربة السابقة","الخلط بين توقع المطر وتوقع التصريف"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن فهم التقدير الراداري وعلاقة الانعكاسية بالمطر وتصحيح الانحياز. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع التحقق من تقدير المطر الراداري QPE","تحليل بيانات الأرصاد الهيدرولوجية والإنذار بالفيضانات واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في التحقق من تقدير المطر الراداري QPE"],"level":"advanced","estimated_minutes":45,"sort_order":9980},{"unit_no":7,"slug":"applied-hydro-04","title":"دمج التوقع المطري QPF مع رصد الحوض","summary":"درس تطبيقي في دمج التوقع المطري QPF مع رصد الحوض ضمن الأرصاد الهيدرولوجية والإنذار بالفيضانات، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع دمج التوقع المطري QPF مع رصد الحوض","تحليل بيانات الأرصاد الهيدرولوجية والإنذار بالفيضانات واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في دمج التوقع المطري QPF مع رصد الحوض"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس استخدام التوقع الاحتمالي والمطر المتراكم والرصد الحالي. ضمن سياق دمج المطر والرادار ورطوبة التربة والأحواض مع التوقعات لدعم الإنذار الهيدرولوجي.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["مقاييس المطر والرادار ومنتجات QPE وQPF","رطوبة التربة والتدفق ومستوى الأنهار","خصائص الحوض والانحدار واستخدام الأرض","سجلات الفيضانات والعتبات المحلية"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الحوض وفترة الاستجابة ومقياس القرار","افحص المطر المرصود والمتوقع وتوزيعه المكاني","ادمج حالة الحوض السابقة وخصائص التصريف","قارن المخرجات بعتبات محلية موثقة"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: دمج التوقع المطري QPF مع رصد الحوض","text":"مجموعة توقعات تقدم نطاقات مطر مختلفة فوق حوض سريع الاستجابة. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"أنشئ ثلاثة سيناريوهات واشرح تغير الثقة. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["استخدام عتبة واحدة لكل الأحواض","إهمال رطوبة التربة السابقة","الخلط بين توقع المطر وتوقع التصريف"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن استخدام التوقع الاحتمالي والمطر المتراكم والرصد الحالي. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع دمج التوقع المطري QPF مع رصد الحوض","تحليل بيانات الأرصاد الهيدرولوجية والإنذار بالفيضانات واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في دمج التوقع المطري QPF مع رصد الحوض"],"level":"advanced","estimated_minutes":35,"sort_order":9990},{"unit_no":7,"slug":"applied-hydro-05","title":"تقدير ذروة التصريف وزمن الوصول","summary":"درس تطبيقي في تقدير ذروة التصريف وزمن الوصول ضمن الأرصاد الهيدرولوجية والإنذار بالفيضانات، مع بيانات ومنهجية و