 from jsonb_to_recordset($payload$[{"unit_no":8,"slug":"applied-urban-01","title":"اختيار مواقع محطات المناخ الحضري","summary":"درس تطبيقي في اختيار مواقع محطات المناخ الحضري ضمن الأرصاد الحضرية والتخطيط المناخي للمدن، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع اختيار مواقع محطات المناخ الحضري","تحليل بيانات الأرصاد الحضرية والتخطيط المناخي للمدن واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في اختيار مواقع محطات المناخ الحضري"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس مبادئ التعرض والارتفاع والتمثيل المكاني وتوثيق البيئة المحيطة. ضمن سياق تحليل المناخ الدقيق داخل المدن وربط الرصد والتصميم الحضري بالمخاطر والخدمات.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["شبكات محطات حضرية متعددة الارتفاعات","صور حرارية وبيانات استخدام الأراضي والغطاء النباتي","هندسة الشوارع ومواد الأسطح والظل","بيانات السكان والطاقة والمياه بصورة مجمعة"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد مقياس الحي أو الشارع أو المبنى","افصل أثر الطقس واسع النطاق عن الشكل الحضري","قارن مواقع ممثلة مع توثيق ارتفاع الحساس والتعرض","ترجم النتيجة إلى مؤشر تخطيط قابل للمتابعة"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: اختيار مواقع محطات المناخ الحضري","text":"مدينة افتراضية فيها شوارع ضيقة وحدائق وساحات واسعة. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اقترح شبكة محطات مع وصف ما تمثله كل محطة. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["مقارنة محطات بارتفاعات مختلفة دون تصحيح","استخدام حرارة سطح القمر بديلاً لحرارة الهواء","تعميم نتائج حي واحد على المدينة"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن مبادئ التعرض والارتفاع والتمثيل المكاني وتوثيق البيئة المحيطة. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع اختيار مواقع محطات المناخ الحضري","تحليل بيانات الأرصاد الحضرية والتخطيط المناخي للمدن واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في اختيار مواقع محطات المناخ الحضري"],"level":"advanced","estimated_minutes":35,"sort_order":10060},{"unit_no":8,"slug":"applied-urban-02","title":"خرائط الحرارة الحضرية متعددة المصادر","summary":"درس تطبيقي في خرائط الحرارة الحضرية متعددة المصادر ضمن الأرصاد الحضرية والتخطيط المناخي للمدن، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع خرائط الحرارة الحضرية متعددة المصادر","تحليل بيانات الأرصاد الحضرية والتخطيط المناخي للمدن واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في خرائط الحرارة الحضرية متعددة المصادر"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس دمج حرارة الهواء والسطح والرصد المتنقل والأقمار الصناعية. ضمن سياق تحليل المناخ الدقيق داخل المدن وربط الرصد والتصميم الحضري بالمخاطر والخدمات.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["شبكات محطات حضرية متعددة الارتفاعات","صور حرارية وبيانات استخدام الأراضي والغطاء النباتي","هندسة الشوارع ومواد الأسطح والظل","بيانات السكان والطاقة والمياه بصورة مجمعة"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد مقياس الحي أو الشارع أو المبنى","افصل أثر الطقس واسع النطاق عن الشكل الحضري","قارن مواقع ممثلة مع توثيق ارتفاع الحساس والتعرض","ترجم النتيجة إلى مؤشر تخطيط قابل للمتابعة"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: خرائط الحرارة الحضرية متعددة المصادر","text":"خريطة افتراضية تظهر سطحاً ساخناً وحديقة أبرد في التوقيت نفسه. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر الفروق ولماذا لا تتساوى حرارة السطح والهواء. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["مقارنة محطات بارتفاعات مختلفة دون تصحيح","استخدام حرارة سطح القمر بديلاً لحرارة الهواء","تعميم نتائج حي واحد على المدينة"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن دمج حرارة الهواء والسطح والرصد المتنقل والأقمار الصناعية. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع خرائط الحرارة الحضرية متعددة المصادر","تحليل بيانات الأرصاد الحضرية والتخطيط المناخي للمدن واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في خرائط الحرارة الحضرية متعددة المصادر"],"level":"advanced","estimated_mi