 from jsonb_to_recordset($payload$[{"unit_no":9,"slug":"applied-health-01","title":"مقارنة مؤشرات الإجهاد الحراري","summary":"درس تطبيقي في مقارنة مؤشرات الإجهاد الحراري ضمن الأرصاد الحيوية والخدمات المناخية الصحية، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع مقارنة مؤشرات الإجهاد الحراري","تحليل بيانات الأرصاد الحيوية والخدمات المناخية الصحية واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في مقارنة مؤشرات الإجهاد الحراري"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس اختلاف WBGT ومؤشر الحرارة والحرارة الظاهرية ومدخلات كل منها. ضمن سياق توظيف المعلومات الجوية والمناخية لدعم التخطيط الصحي والتواصل الوقائي بالتعاون مع الجهات المختصة.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["الحرارة والرطوبة والرياح والإشعاع وUV","بيانات صحية مجمعة ومجهولة الهوية","تقويم المدارس والعمل والفعاليات ومؤشرات التعرض","سجلات المناخ والإنذارات الصحية المعتمدة"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الفئة والفترة ومؤشر التعرض المناسب","تحقق من الجودة والتمثيل وحماية الخصوصية","قارن المؤشر بالمعيار الصحي الرسمي المحلي","نسق الرسالة مع السلطات الصحية ووضح عدم اليقين"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: مقارنة مؤشرات الإجهاد الحراري","text":"حالة افتراضية تختلف فيها الرطوبة والإشعاع مع ثبات حرارة الهواء. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن المؤشرات وفسر اختلاف دلالتها حسب النشاط والتعرض. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["تقديم مؤشر جوي بوصفه تشخيصاً طبياً","الخلط بين الارتباط والسببية","نشر بيانات صحية شخصية أو صغيرة العدد"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن اختلاف WBGT ومؤشر الحرارة والحرارة الظاهرية ومدخلات كل منها. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع مقارنة مؤشرات الإجهاد الحراري","تحليل بيانات الأرصاد الحيوية والخدمات المناخية الصحية واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في مقارنة مؤشرات الإجهاد الحراري"],"level":"advanced","estimated_minutes":35,"sort_order":10160},{"unit_no":9,"slug":"applied-health-02","title":"رصد مخاطر البرد والرياح","summary":"درس تطبيقي في رصد مخاطر البرد والرياح ضمن الأرصاد الحيوية والخدمات المناخية الصحية، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع رصد مخاطر البرد والرياح","تحليل بيانات الأرصاد الحيوية والخدمات المناخية الصحية واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في رصد مخاطر البرد والرياح"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس تحليل الحرارة المحسوسة والرياح ومدة التعرض وفق الإرشادات الرسمية. ضمن سياق توظيف المعلومات الجوية والمناخية لدعم التخطيط الصحي والتواصل الوقائي بالتعاون مع الجهات المختصة.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["الحرارة والرطوبة والرياح والإشعاع وUV","بيانات صحية مجمعة ومجهولة الهوية","تقويم المدارس والعمل والفعاليات ومؤشرات التعرض","سجلات المناخ والإنذارات الصحية المعتمدة"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الفئة والفترة ومؤشر التعرض المناسب","تحقق من الجودة والتمثيل وحماية الخصوصية","قارن المؤشر بالمعيار الصحي الرسمي المحلي","نسق الرسالة مع السلطات الصحية ووضح عدم اليقين"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: رصد مخاطر البرد والرياح","text":"موجة برد افتراضية تتزامن مع رياح قوية في منطقة مكشوفة. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم ملخص تعرض يوضح المؤشرات والمدة وحدود التفسير. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["تقديم مؤشر جوي بوصفه تشخيصاً طبياً","الخلط بين الارتباط والسببية","نشر بيانات صحية شخصية أو صغيرة العدد"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن تحليل الحرارة المحسوسة والرياح ومدة التعرض وفق الإرشادات الرسمية. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع رصد مخاطر البرد والرياح","تحليل بيانات الأرصاد الحيوية والخدمات المناخية الصحية واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في رصد مخاطر البرد والرياح"],"level":"advanced","estimated_minutes":40,"sort_order":10170},{"unit_no":9,"slug":"applied-health-03","tit