 from jsonb_to_recordset($payload$[{"unit_no":10,"slug":"applied-climate-01","title":"الخطر والتعرض والهشاشة","summary":"درس تطبيقي في الخطر والتعرض والهشاشة ضمن إدارة مخاطر المناخ والتكيف القطاعي، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع الخطر والتعرض والهشاشة","تحليل بيانات إدارة مخاطر المناخ والتكيف القطاعي واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في الخطر والتعرض والهشاشة"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس تفكيك مخاطر المناخ إلى مكونات قابلة للتحليل وتحديد دور كل مكون. ضمن سياق تحويل معلومات المناخ والتوقعات إلى تقييم مخاطر وخيارات تكيف قابلة للمتابعة.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list","items":["سلاسل مناخية متجانسة ومؤشرات التطرف","إسقاطات مناخية وسيناريوهات وانحيازاتها","بيانات التعرض والحساسية والقدرة على التكيف","خطط القطاعات والبنية التحتية والأطر التنظيمية"]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد الخطر والقطاع والأفق الزمني","حلل الخطر والتعرض والحساسية والقدرة منفصلة","قارن السيناريوهات ولا تخلطها بالتوقع التشغيلي","صمم خيارات تكيف ومؤشرات متابعة"]},{"type":"heading","text":"حالة تطبيقية"},{"type":"example","title":"مثال تدريبي: الخطر والتعرض والهشاشة","text":"منطقتان لهما الخطر نفسه لكن تختلفان في التعرض والقدرة على التكيف. تعامل مع القيم الواردة بوصفها بيانات افتراضية للتدريب، ولا تستخدمها لاتخاذ قرار تشغيلي حقيقي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"أنشئ مصفوفة تميز الخطر عن الأثر المتوقع. قدم النتيجة في جدول أو مخطط صغير، واكتب الوحدات ومصدر كل متغير وافتراضاتك وما لا تسمح البيانات باستنتاجه."},{"type":"heading","text":"أخطاء ينبغي تجنبها"},{"type":"list","items":["التعامل مع سيناريو مناخي كتوقع مؤكد","إغفال عدم اليقين والاختلاف المكاني","تقييم الخطر دون معرفة الأصول والفئات المعرضة"]},{"type":"callout","text":"تنبيه مهني: هذا الدرس تدريب تحليلي. يجب الرجوع إلى المعايير والعتبات والسلطات المختصة في القطاع قبل استخدام أي نتيجة في قرار فعلي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"الخلاصة أن تفكيك مخاطر المناخ إلى مكونات قابلة للتحليل وتحديد دور كل مكون. يحتاج إلى دمج الرصد والسياق المكاني والزمني والتحقق من جودة البيانات. المنتج الجيد يبين ما نعرفه وما لا نعرفه، ويحدد متى يجب تحديثه ومن الجهة التي تملك قرار التنفيذ."}]},"learning_objectives":["شرح المبادئ العلمية المرتبطة بموضوع الخطر والتعرض والهشاشة","تحليل بيانات إدارة مخاطر المناخ والتكيف القطاعي واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في الخطر والتعرض والهشاشة"],"level":"advanced","estimated_minutes":35,"sort_order":10260},{"unit_no":10,"slug":"applied-climate-02","title":"اختيار مؤشرات المناخ المتطرف","summary":"درس تطبيقي في اختيار مؤشرات المناخ المتطرف ضمن إدارة مخاطر المناخ والتكيف القطاعي، مع بيانات ومنهجية ومثال ومهمة تدريبية.","content":{"blocks":[{"type":"heading","text":"نواتج التعلم"},{"type":"list","items":["شرح المبادئ العلمية المرتبطة بموضوع اختيار مؤشرات المناخ المتطرف","تحليل بيانات إدارة مخاطر المناخ والتكيف القطاعي واستخلاص مؤشرات قابلة للتفسير","إعداد تطبيق عملي يراعي حدود البيانات وعدم اليقين في اختيار مؤشرات المناخ المتطرف"]},{"type":"heading","text":"المفهوم العلمي والتشغيلي"},{"type":"text","text":"يتناول هذا الدرس فهم مؤشرات موجات الحر والأمطار الشديدة والليالي الدافئة وفترات الجفاف. ضمن سياق تحويل معلومات المناخ والتوقعات إلى تقييم مخاطر وخيارات تكيف قابلة للمتابعة.، ويؤكد الفصل بين القياس المباشر والمؤشر المحسوب والتوقع النموذجي. لا تفسر قيمة منفردة بمعزل عن زمنها وموقعها وارتفاع القياس وطريقة المعالجة. وثّق الوحدات والفترة المرجعية والافتراضات قبل تحويل التحليل إلى معلومة تشغيلية."},{"type":"heading","text":"البيانات والمدخلات"},{"type":"list